import org.hamcrest.core.IsInstanceOf;
import org.jsoup.Connection;
import org.jsoup.HttpStatusException;
import org.jsoup.nodes.Document;
import org.jsoup.parser.Parser;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.runners.MockitoJUnitRunner;

import javax.net.ssl.SSLSocketFactory;
import java.io.IOException;
import java.io.InputStream;
import java.net.*;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

@RunWith(MockitoJUnitRunner.class)
public class HttpConnectionTest {

    @Test
    public void connectUrlStringTest() {
        Connection connection = HttpConnection.connect("https://www.google.com");
        assertNotNull(connection);
    }

    @Test(expected = IllegalArgumentException.class)
    public void connectUrlStringInvalidUrlTest() {
        Connection connection = HttpConnection.connect("InvalidUrl");
    }

    @Test
    public void connectUrlTest() throws MalformedURLException {
        Connection connection = HttpConnection.connect(new URL("https://www.google.com"));
        assertNotNull(connection);
    }

    @Test
    public void proxyTest() {
        Connection connection = new HttpConnection().proxy(new Proxy(Proxy.Type.HTTP, new InetSocketAddress("127.0.0.1", 8080)));
        assertNotNull(connection);
    }

    @Test
    public void proxyStringTest() {
        Connection connection = new HttpConnection().proxy("127.0.0.1", 8080);
        assertNotNull(connection);
    }

    @Test
    public void requestMethodTest() {
        Connection connection = new HttpConnection().method(Connection.Method.POST);
        assertEquals(Connection.Method.POST, connection.request().method());
    }

    @Test
    public void userAgentTest() {
        Connection connection = new HttpConnection().userAgent("Mozilla");
        assertEquals("Mozilla", connection.request().userAgent());
    }

    @Test
    public void getUrlTest() throws MalformedURLException {
        Connection connection = new HttpConnection().url(new URL("https://www.google.com"));
        assertEquals(new URL("https://www.google.com"), connection.request().url());
    }

    @Test
    public void followRedirectsTest() {
        Connection connection = new HttpConnection().followRedirects(true);
        assertTrue(connection.request().followRedirects());
    }

    @Test
    public void sslSocketFactoryTest() {
        Connection connection = new HttpConnection().sslSocketFactory((SSLSocketFactory) SSLSocketFactory.getDefault());
        assertEquals(SSLSocketFactory.getDefault(), connection.request().sslSocketFactory());
    }

    @Test
    public void responseMethodTest() {
        Connection.Response response = new HttpConnection().response();
        assertNotNull(response);
    }

    @Test(expected = HttpStatusException.class)
    public void getInvalidUrlTest() throws IOException {
        Document document = new HttpConnection().url("https://nonexistingpage123123.com").get();
    }

    @Test
    public void newRequestMethodTest() {
        Connection connection = new HttpConnection().newRequest();
        assertNotNull(connection.request());
    }

    @Test
    public void parserTest() {
        Parser parser = Parser.htmlParser();
        Connection connection = new HttpConnection().parser(parser);
        assertEquals(parser, connection.request().parser());
    }
}
